style.css:
@-moz-document domain("docs.google.com") {
/* ? Gradient background */
    body {
        background: linear-gradient(135deg, #87cefa, #ffb6f0) !important;
    }

    /* ? Document area */
    .kix-appview-editor {
        background: white !important;
        box-shadow: 0 0 30px rgba(255, 182, 240, 0.6),
                    0 0 50px rgba(135, 206, 250, 0.6);
        border-radius: 12px;
        margin: 20px auto !important;
    }

    /* ✨ Top menu bar */
    .docs-menubar,
    .docs-titlebar {
        background: rgba(255, 182, 240, 0.7) !important;
        backdrop-filter: blur(8px);
        color: #4a004e !important;
    }

    /* ? Toolbar area */
    .kix-appview-editor-container,
    .docs-ui-unprintable {
        background: rgba(135, 206, 250, 0.6) !important;
        backdrop-filter: blur(6px);
    }

    /* ? Buttons */
    .goog-toolbar-button,
    .docs-material-button,
    .goog-flat-menu-button {
        background: #ffb6f0 !important;
        border-radius: 8px !important;
        color: #4a004e !important;
        border: none !important;
        transition: 0.3s ease;
    }

    /* ? Hover effect */
    .goog-toolbar-button:hover,
    .docs-material-button:hover,
    .goog-flat-menu-button:hover {
        background: #87cefa !important;
        color: white !important;
        transform: scale(1.05);
    }

    /* ? Fonts in menu */
    .docs-menubar span,
    .docs-title-input-label-inner {
        color: #4a004e !important;
        font-weight: bold !important;
    }
}
